    def fail_nicely_if_excess_widgets(apps, schema_editor):
        Node = apps.get_model("models", "Node")
        nodes_with_excess_widgets = (
            Node.objects.annotate(
                source_widget_count=models.Count(
                    "cardxnodexwidget", filter=models.Q(source_identifier__isnull=True)
                ),
                draft_widget_count=models.Count(
                    "cardxnodexwidget", filter=models.Q(source_identifier__isnull=False)
                ),
            )
            .filter(
                models.Q(source_widget_count__gt=1) | models.Q(draft_widget_count__gt=1)
            )
            .prefetch_related("nodegroup__cardmodel_set")
        )

        if problems_remain := deduplicate_widgets(nodes_with_excess_widgets):
            raise Exception(
                "Nodes with excess widgets found. Run manage.py validate "
                "(optionally with --verbosity 2) to get a report. This can "
                "be partially fixed by running `manage.py validate --fix 1016`, "
                "but all additional excess widgets must be removed before "
                "proceeding with this migration."
            )

    def set_active_true(apps, schema_editor):
        GraphModel = apps.get_model("models", "GraphModel")
        # Select published graphs without any draft graphs.
        GraphModel.objects.filter(
            draft=None,
            publication__isnull=False,
        ).update(is_active=True)

    def add_missing_graph_slug(apps, schema_editor):
        Graph = apps.get_model("models", "Graph")
        graphs_missing_slug = Graph.objects.filter(slug__isnull=True)
        for graph in graphs_missing_slug:
            existing_graph_slugs = Graph.objects.all().values_list("slug", flat=True)
            slug = slugify(str(graph.name) or "new_graph", separator="_")
            graph.slug = make_name_unique(slug, existing_graph_slugs)
            graph.save()

    def add_grouping_node(apps, schema_editor):
        NodeGroup = apps.get_model("models", "NodeGroup")
        nodegroups_with_nodes = NodeGroup.objects.filter(node__gt=0).distinct()
        for nodegroup in nodegroups_with_nodes:
            nodegroup.grouping_node_id = nodegroup.pk
        NodeGroup.objects.bulk_update(nodegroups_with_nodes, ["grouping_node_id"])

        PublishedGraph = apps.get_model("models", "PublishedGraph")
        published_graphs = PublishedGraph.objects.all()
        for published_graph in published_graphs:
            for nodegroup_dict in published_graph.serialized_graph["nodegroups"]:
                nodegroup_dict["grouping_node_id"] = nodegroup_dict["nodegroupid"]
        PublishedGraph.objects.bulk_update(published_graphs, ["serialized_graph"])

    def remove_grouping_node(apps, schema_editor):
        PublishedGraph = apps.get_model("models", "PublishedGraph")
        published_graphs = PublishedGraph.objects.all()
        for published_graph in published_graphs:
            for nodegroup_dict in published_graph.serialized_graph["nodegroups"]:
                nodegroup_dict.pop("grouping_node_id", None)
        PublishedGraph.objects.bulk_update(published_graphs, ["serialized_graph"])

